{
  "name": "@madsoftwaredev/opencode-sidebar-resize",
  "version": "0.1.2",
  "description": "OpenCode V2 TUI plugin for resizing the existing session sidebar by dragging or command.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "sidebar",
    "resize",
    "tui"
  ],
  "license": "MIT",
  "author": "MadSoftwareDev",
  "type": "module",
  "exports": {
    "./tui": "./tui.tsx"
  },
  "files": [
    "tui.tsx",
    "sidebar.ts",
    "width.ts",
    "README.md",
    "LICENSE"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/madsoftwaredev/opencode-plugins.git",
    "directory": "packages/sidebar-resize"
  },
  "homepage": "https://github.com/madsoftwaredev/opencode-plugins/tree/main/packages/sidebar-resize#readme",
  "bugs": {
    "url": "https://github.com/madsoftwaredev/opencode-plugins/issues"
  },
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "test": "bun test --preload @opentui/solid/preload",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "^2.1.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.12"
  },
  "devDependencies": {
    "@opentui/core": "0.8.1",
    "@opentui/solid": "0.8.1",
    "@types/bun": "1.4.0",
    "typescript": "5.8.2"
  },
  "publishConfig": {
    "access": "public"
  }
}
